"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[1734],{772(n,e,a){a.r(e),a.d(e,{assets:()=>d,contentTitle:()=>c,default:()=>u,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part5-deep-learning-and-llms/ffn-training-debugging","title":"Feed-Forward Networks: Training, Evaluation, and Debugging","description":"Training at scale with mini-batches, evaluation (accuracy + confusion matrix), and a synthetic regression example for visual intuition.","source":"@site/docs/part5-deep-learning-and-llms/02-ffn-training-debugging.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/02-ffn-training-debugging","permalink":"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":2,"frontMatter":{"title":"Feed-Forward Networks: Training, Evaluation, and Debugging","slug":"/part5-deep-learning-and-llms/02-ffn-training-debugging","description":"Training at scale with mini-batches, evaluation (accuracy + confusion matrix), and a synthetic regression example for visual intuition.","sidebar_label":"2. FFN training and debugging","pagination_label":"2. FFN training and debugging","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"1. Feed-forward network concepts","permalink":"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts"},"next":{"title":"3. FFN single-chapter reference","permalink":"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged"}}');var t=a(4848),s=a(8453),o=a(8172);const r=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/02-ffn-training-debugging.html","route":"/part5-deep-learning-and-llms/02-ffn-training-debugging","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Feed-Forward Networks: Training, Evaluation, and Debugging","title":"Feed-Forward Networks: Training, Evaluation, and Debugging","description":"Training at scale with mini-batches, evaluation (accuracy + confusion matrix), and a synthetic regression example for visual intuition.","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-mini-batches-the-practical-way-to-train-on-large-datasets","label":"1) Mini-batches: the practical way to train on large datasets"},{"id":"2-data-pipeline-datasets-transforms-and-dataloader","label":"2) Data pipeline: datasets, transforms, and DataLoader"},{"id":"3-training-loop-patterns-that-scale","label":"3) Training loop patterns that scale"},{"id":"4-accuracy-when-your-data-arrives-in-batches","label":"4) Accuracy when your data arrives in batches"},{"id":"5-logits-vs-probabilities-why-argmax-is-enough-for-predictions","label":"5) Logits vs probabilities: why argmax is enough for predictions"},{"id":"6-gpu-usage-avoid-tensors-on-different-devices-errors","label":"6) GPU usage: avoid \u201ctensors on different devices\u201d errors"},{"id":"7-debugging-classification-confusion-matrix-misclassified-samples","label":"7) Debugging classification: confusion matrix + misclassified samples"},{"id":"8-synthetic-regression-fit-a-non-linear-surface-you-can-visualize","label":"8) Synthetic regression: fit a non-linear surface you can visualize"},{"id":"9-hyperparameters-a-practical-experimentation-workflow","label":"9) Hyperparameters: a practical experimentation workflow"},{"id":"local-visuals-and-source-credits","label":"Local visuals and source credits"}],"html":"<div class=\\"wrap\\">\\n    <header>\\n      \\n      <p>\\n        <span class=\\"pill\\">Training at scale</span> with mini-batches,\\n        <span class=\\"pill\\">evaluation</span> (accuracy + confusion matrix),\\n        and a <span class=\\"pill\\">synthetic regression</span> example for visual intuition.\\n      </p>\\n\\n      <div class=\\"chips\\">\\n        <span class=\\"chip\\">Mini-batch gradient descent</span>\\n        <span class=\\"chip\\">Argmax over logits</span>\\n        <span class=\\"chip\\">Accuracy over DataLoader</span>\\n        <span class=\\"chip\\">GPU device placement</span>\\n        <span class=\\"chip\\">Confusion matrix + error analysis</span>\\n        <span class=\\"chip\\">Synthetic data + surface fitting</span>\\n      </div>\\n\\n      <nav>\\n        <a href=\\"#mbgd\\">Mini-batches &amp; why they work</a>\\n        <a href=\\"#pipeline\\">Data pipeline &amp; transforms</a>\\n        <a href=\\"#trainloop\\">Training loop patterns</a>\\n        <a href=\\"#accuracy\\">Accuracy with batches</a>\\n        <a href=\\"#argmax\\">Logits, softmax, argmax</a>\\n        <a href=\\"#gpu\\">GPU: keeping tensors on one device</a>\\n        <a href=\\"#confmat\\">Confusion matrix &amp; mistakes</a>\\n        <a href=\\"#synthetic\\">Synthetic regression surface</a>\\n        <a href=\\"#tuning\\">Hyperparameter tuning mindset</a>\\n        <a href=\\"#credits\\">Online plots used</a>\\n      </nav>\\n    </header>\\n\\n    <section id=\\"mbgd\\">\\n      <h2 id=\\"1-mini-batches-the-practical-way-to-train-on-large-datasets\\">1) Mini-batches: the practical way to train on large datasets</h2>\\n\\n      <p>\\n        Most training objectives are averages over a dataset. If your dataset has \\\\(N\\\\) samples and per-sample loss \\\\(\\\\ell_i(\\\\theta)\\\\),\\n        the empirical risk is:\\n      </p>\\n      <p>\\n        \\\\[\\n          L(\\\\theta) = \\\\frac{1}{N}\\\\sum_{i=1}^N \\\\ell_i(\\\\theta)\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        Computing \\\\(\\\\nabla_\\\\theta L(\\\\theta)\\\\) over all \\\\(N\\\\) samples every step is expensive. Instead, we use a mini-batch \\\\(B\\\\)\\n        (a small random subset) and approximate the loss and gradient:\\n      </p>\\n      <p>\\n        \\\\[\\n          \\\\widehat{L}_B(\\\\theta) = \\\\frac{1}{|B|}\\\\sum_{i\\\\in B}\\\\ell_i(\\\\theta),\\n          \\\\quad\\n          \\\\nabla_\\\\theta \\\\widehat{L}_B(\\\\theta) \\\\approx \\\\nabla_\\\\theta L(\\\\theta)\\n        \\\\]\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Intuition:</b> if batches are shuffled, each batch is a \u201crepresentative sample\u201d of the dataset.\\n          Over many steps, you still see the whole dataset, but each update is much cheaper.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Optimizer animations (SGD and friends)\\" src=\\"/tutorials/images/external/Optimizer_Animations-9d82ec1a32-fallback.svg\\">\\n        <figcaption>\\n          Optimizer behavior (Wikimedia Commons): <a href=\\"https://commons.wikimedia.org/wiki/File:Optimizer_Animations.gif\\" target=\\"_blank\\" rel=\\"noopener\\">Optimizer_Animations.gif</a>\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"pipeline\\">\\n      <h2 id=\\"2-data-pipeline-datasets-transforms-and-dataloader\\">2) Data pipeline: datasets, transforms, and DataLoader</h2>\\n\\n      <p>\\n        A clean PyTorch pipeline usually has three parts:\\n      </p>\\n      <ol>\\n        <li><b>Dataset</b>: knows how to fetch one sample \\\\((x,y)\\\\)</li>\\n        <li><b>Transform(s)</b>: preprocessing applied per sample</li>\\n        <li><b>DataLoader</b>: batching, shuffling, parallel loading</li>\\n      </ol>\\n\\n      <h3 id=\\"mnist-why-values-become-0-1-only-when-transformed\\">MNIST: why values become 0\u20131 only when transformed</h3>\\n      <p class=\\"muted\\">\\n        MNIST is stored as 8-bit integers (0\u2013255). <code>transforms.ToTensor()</code> converts to float and scales to \\\\([0,1]\\\\).\\n        If you inspect raw stored tensors, you\u2019ll see 0\u2013255. If you iterate through the DataLoader with the transform, you\u2019ll see 0\u20131.\\n      </p>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 verify raw vs transformed MNIST ranges</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>from torchvision import datasets, transforms\\n\\ntrain_raw = datasets.MNIST(root=\\"data\\", train=True, download=True, transform=None)\\nprint(\\"raw dtype:\\", train_raw.data.dtype)\\nprint(\\"raw min/max:\\", int(train_raw.data.min()), int(train_raw.data.max()))  # typically 0..255\\n\\ntrain_tf = datasets.MNIST(root=\\"data\\", train=True, download=True, transform=transforms.ToTensor())\\nx0, y0 = train_tf[0]\\nprint(\\"transformed dtype:\\", x0.dtype)\\nprint(\\"transformed min/max:\\", float(x0.min()), float(x0.max()))  # typically 0..1</code></pre>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Rule of thumb:</b> keep preprocessing inside the Dataset via <code>transform=...</code>.\\n          That way every training/eval pass uses the same consistent inputs.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"trainloop\\">\\n      <h2 id=\\"3-training-loop-patterns-that-scale\\">3) Training loop patterns that scale</h2>\\n\\n      <p>\\n        A robust training loop separates:\\n      </p>\\n      <ul>\\n        <li><b>training mode</b> (updates parameters) vs <b>evaluation mode</b> (no updates)</li>\\n        <li><b>metrics</b> computed batch-by-batch</li>\\n        <li><b>device transfers</b> done once per batch</li>\\n      </ul>\\n\\n      <h3 id=\\"one-update-step-on-a-batch\\">One update step on a batch</h3>\\n      <p>\\n        For a batch \\\\((x_B, y_B)\\\\), gradient descent performs:\\n      </p>\\n      <p>\\n        \\\\[\\n          \\\\theta \\\\leftarrow \\\\theta - \\\\eta \\\\nabla_\\\\theta \\\\widehat{L}_B(\\\\theta)\\n        \\\\]\\n      </p>\\n\\n      <h3 id=\\"canonical-pytorch-inner-loop\\">Canonical PyTorch \u201cinner loop\u201d</h3>\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 canonical mini-batch update step</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>model.train()                 # enables train-time behavior (e.g., dropout/bn)\\nfor x, y in train_loader:\\n    x, y = x.to(device), y.to(device)\\n\\n    optimizer.zero_grad()     # clear old gradients\\n    logits = model(x)         # forward pass\\n    loss = criterion(logits, y)\\n\\n    loss.backward()           # compute gradients\\n    optimizer.step()          # update parameters</code></pre>\\n      </div>\\n\\n      <h3 id=\\"epoch-loss-average-over-batches\\">Epoch loss: average over batches</h3>\\n      <p class=\\"muted\\">\\n        If you collect per-batch losses \\\\(\\\\{\\\\widehat{L}_{B_k}\\\\}\\\\) in one epoch, a common summary is the mean:\\n        \\\\[\\n          \\\\text{epoch\\\\_loss} = \\\\frac{1}{K}\\\\sum_{k=1}^K \\\\widehat{L}_{B_k}\\n        \\\\]\\n        This is a practical proxy for \u201chow training is going\u201d without doing a second full pass just to re-measure loss.\\n      </p>\\n    </section>\\n\\n    <section id=\\"accuracy\\">\\n      <h2 id=\\"4-accuracy-when-your-data-arrives-in-batches\\">4) Accuracy when your data arrives in batches</h2>\\n\\n      <p>\\n        When data comes via a DataLoader, you usually can\u2019t compute accuracy in one shot.\\n        The simple fix is to accumulate counts.\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          \\\\text{accuracy} = \\\\frac{\\\\sum_{i=1}^{N} \\\\mathbb{1}\\\\{\\\\hat{y}_i = y_i\\\\}}{N}\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        With batches, you compute \u201ccorrect in this batch\u201d and \u201cbatch size\u201d, then add them up.\\n      </p>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 batched accuracy over a DataLoader</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>@torch.no_grad()\\ndef accuracy_loader(model, loader, device):\\n    model.eval()\\n    correct = 0\\n    total = 0\\n    for x, y in loader:\\n        x, y = x.to(device), y.to(device)\\n        logits = model(x)\\n        pred = logits.argmax(dim=1)           # class index\\n        correct += (pred == y).sum().item()\\n        total += y.numel()\\n    return correct / total</code></pre>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Tip:</b> use <code>@torch.no_grad()</code> in evaluation to reduce memory usage and speed things up.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"argmax\\">\\n      <h2 id=\\"5-logits-vs-probabilities-why-argmax-is-enough-for-predictions\\">5) Logits vs probabilities: why argmax is enough for predictions</h2>\\n\\n      <p>\\n        Many classification models output <b>logits</b> \\\\(z \\\\in \\\\mathbb{R}^K\\\\). Softmax converts logits into probabilities:\\n      </p>\\n      <p>\\n        \\\\[\\n          \\\\mathrm{softmax}(z)_i = \\\\frac{e^{z_i}}{\\\\sum_{j=1}^K e^{z_j}}\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        For <b>choosing the predicted class</b>, you almost never need the probabilities. You only need:\\n        \\\\[\\n          \\\\hat{y} = \\\\arg\\\\max_i z_i\\n        \\\\]\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Key fact:</b> <code>argmax(softmax(z)) == argmax(z)</code>. Exponentials preserve ordering and the denominator is shared.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Softmax illustration (English)\\" src=\\"/tutorials/images/external/Softmax_en-13b6657f61-fallback.svg\\">\\n        <figcaption>\\n          Softmax illustration (Wikimedia Commons): <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax_en.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Softmax_en.svg</a>\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"pytorch-get-indices-classes-from-logits\\">PyTorch: get indices (classes) from logits</h3>\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 logits \u2192 predicted class indices</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>logits = model(x)            # shape: (B, K)\\npred = torch.argmax(logits, dim=1)  # shape: (B,)</code></pre>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        If you want probabilities for interpretability (e.g., confidence), you can still compute:\\n        <code>probs = torch.softmax(logits, dim=1)</code>.\\n        For training with <code>nn.CrossEntropyLoss</code>, keep the model output as logits.\\n      </p>\\n    </section>\\n\\n    <section id=\\"gpu\\">\\n      <h2 id=\\"6-gpu-usage-avoid-tensors-on-different-devices-errors\\">6) GPU usage: avoid \u201ctensors on different devices\u201d errors</h2>\\n\\n      <p>\\n        In PyTorch, your model parameters live on a device (CPU or GPU). Your data must be on the same device\\n        before you do operations between them.\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Do:</b>\\n            <br>\u2022 <code>model.to(device)</code>\\n            <br>\u2022 <code>x.to(device), y.to(device)</code> each batch\\n          </p>\\n        </div>\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Don\u2019t:</b>\\n            <br>\u2022 keep model on GPU and data on CPU (or vice versa)\\n            <br>\u2022 mix tensors across devices in one computation\\n          </p>\\n        </div>\\n      </div>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 device selection + consistent placement</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>device = torch.device(\\"cuda\\" if torch.cuda.is_available() else \\"cpu\\")\\nmodel = model.to(device)\\n\\nfor x, y in train_loader:\\n    x, y = x.to(device), y.to(device)\\n    logits = model(x)\\n    ...</code></pre>\\n      </div>\\n    </section>\\n\\n    <section id=\\"confmat\\">\\n      <h2 id=\\"7-debugging-classification-confusion-matrix-misclassified-samples\\">7) Debugging classification: confusion matrix + misclassified samples</h2>\\n\\n      <p>\\n        Overall accuracy hides <i>which</i> classes are being confused. A confusion matrix breaks errors down by class.\\n        For a \\\\(K\\\\)-class problem, it\u2019s a \\\\(K \\\\times K\\\\) table where entry \\\\((i,j)\\\\) counts:\\n        \u201ctrue label \\\\(i\\\\) predicted as \\\\(j\\\\)\u201d.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Confusion matrix example\\" src=\\"/tutorials/images/external/Confusion_matrix-71f9dc8b35-fallback.svg\\">\\n        <figcaption>\\n          Confusion matrix example (Wikimedia Commons): <a href=\\"https://commons.wikimedia.org/wiki/File:Confusion_matrix.png\\" target=\\"_blank\\" rel=\\"noopener\\">Confusion_matrix.png</a>\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"collect-predictions-for-a-full-dataloader-pass\\">Collect predictions for a full DataLoader pass</h3>\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 gather all predictions + labels</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>@torch.no_grad()\\ndef collect_preds(model, loader, device):\\n    model.eval()\\n    all_pred = []\\n    all_y = []\\n    for x, y in loader:\\n        x = x.to(device)\\n        logits = model(x)\\n        pred = logits.argmax(dim=1).cpu()\\n        all_pred.append(pred)\\n        all_y.append(y.cpu())\\n    return torch.cat(all_y), torch.cat(all_pred)</code></pre>\\n      </div>\\n\\n      <h3 id=\\"compute-confusion-matrix-two-options\\">Compute confusion matrix (two options)</h3>\\n\\n      <div class=\\"grid two\\">\\n        <div>\\n          <p class=\\"muted\\"><b>Option A:</b> pure PyTorch (no extra deps)</p>\\n          <div class=\\"codewrap\\">\\n            <div class=\\"codebar\\">\\n              <span class=\\"label\\">python \u2022 confusion matrix in pure torch</span>\\n              \\n            </div>\\n<pre class=\\"language-python\\"><code>def confusion_matrix_torch(y_true, y_pred, num_classes):\\n    cm = torch.zeros((num_classes, num_classes), dtype=torch.int64)\\n    for t, p in zip(y_true, y_pred):\\n        cm[t, p] += 1\\n    return cm\\n\\ny_true, y_pred = collect_preds(model, test_loader, device)\\ncm = confusion_matrix_torch(y_true, y_pred, num_classes=10)\\nprint(cm)</code></pre>\\n          </div>\\n        </div>\\n\\n        <div>\\n          <p class=\\"muted\\"><b>Option B:</b> scikit-learn (convenient)</p>\\n          <div class=\\"codewrap\\">\\n            <div class=\\"codebar\\">\\n              <span class=\\"label\\">python \u2022 confusion matrix via scikit-learn</span>\\n              \\n            </div>\\n<pre class=\\"language-python\\"><code># pip install scikit-learn\\nfrom sklearn.metrics import confusion_matrix\\n\\ny_true, y_pred = collect_preds(model, test_loader, device)\\ncm = confusion_matrix(y_true.numpy(), y_pred.numpy(), labels=list(range(10)))\\nprint(cm)</code></pre>\\n          </div>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"find-and-visualize-misclassified-samples\\">Find and visualize misclassified samples</h3>\\n      <p class=\\"muted\\">\\n        Once you know common confusions, actually look at examples. (The code below generates plots when <i>you</i> run it.)\\n      </p>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 extract misclassified MNIST examples + plot a grid</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import matplotlib.pyplot as plt\\n\\n@torch.no_grad()\\ndef get_misclassified(model, loader, device, max_items=25):\\n    model.eval()\\n    items = []\\n    for x, y in loader:\\n        x, y = x.to(device), y.to(device)\\n        logits = model(x)\\n        pred = logits.argmax(dim=1)\\n        wrong = pred != y\\n        if wrong.any():\\n            xw = x[wrong].cpu()\\n            yw = y[wrong].cpu()\\n            pw = pred[wrong].cpu()\\n            for i in range(xw.size(0)):\\n                items.append((xw[i], int(yw[i]), int(pw[i])))\\n                if len(items) &gt;= max_items:\\n                    return items\\n    return items\\n\\nmis = get_misclassified(model, test_loader, device, max_items=16)\\n\\n# Plot (runs locally; not generated in this HTML)\\nfig, axes = plt.subplots(4, 4, figsize=(6, 6))\\nfor ax, (img, y, p) in zip(axes.ravel(), mis):\\n    ax.imshow(img.squeeze(0), cmap=\\"gray\\")\\n    ax.set_title(f\\"true={y}, pred={p}\\", fontsize=9)\\n    ax.axis(\\"off\\")\\nplt.tight_layout()\\nplt.show()</code></pre>\\n      </div>\\n    </section>\\n\\n    <section id=\\"synthetic\\">\\n      <h2 id=\\"8-synthetic-regression-fit-a-non-linear-surface-you-can-visualize\\">8) Synthetic regression: fit a non-linear surface you can visualize</h2>\\n\\n      <p>\\n        Classification isn\u2019t the only job for feed-forward nets. For regression, the output layer is typically <b>identity</b> (no activation),\\n        and the loss is often mean squared error (MSE).\\n      </p>\\n\\n      <h3 id=\\"define-a-bumpy-2d-function\\">Define a \u201cbumpy\u201d 2D function</h3>\\n      <p>\\n        We\u2019ll sample \\\\(x \\\\in \\\\mathbb{R}^2\\\\) uniformly in a box and define targets:\\n      </p>\\n      <p>\\n        \\\\[\\n          y = \\\\cos(2x_1) + \\\\cos(3x_2)\\n        \\\\]\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"3D surface plot example\\" src=\\"/tutorials/images/external/3-D_surface_plot-dd978c9fe8-fallback.svg\\">\\n        <figcaption>\\n          Example 3D surface plot (Wikimedia Commons): <a href=\\"https://commons.wikimedia.org/wiki/File:3-D_surface_plot.jpg\\" target=\\"_blank\\" rel=\\"noopener\\">3-D_surface_plot.jpg</a>\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"generate-data-3d-scatter-run-locally\\">Generate data + 3D scatter (run locally)</h3>\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 synthetic dataset + 3D scatter</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import numpy as np\\nimport torch\\nimport matplotlib.pyplot as plt\\nfrom mpl_toolkits.mplot3d import Axes3D  # noqa: F401 (needed for 3D)\\n\\n# Reproducibility\\ntorch.manual_seed(0)\\nnp.random.seed(0)\\n\\nN = 5000\\nx = (torch.rand(N, 2) * 6.0) - 3.0                 # uniform in [-3, 3]^2\\ny = torch.cos(2.0 * x[:, 0]) + torch.cos(3.0 * x[:, 1])\\ny = y.unsqueeze(1)                                  # shape (N, 1)\\n\\n# 3D scatter (generated when you run this)\\nfig = plt.figure(figsize=(6, 5))\\nax = fig.add_subplot(111, projection=\\"3d\\")\\nax.scatter(x[:,0].numpy(), x[:,1].numpy(), y[:,0].numpy(), s=3)\\nax.set_xlabel(\\"x1\\"); ax.set_ylabel(\\"x2\\"); ax.set_zlabel(\\"y\\")\\nplt.show()</code></pre>\\n      </div>\\n\\n      <h3 id=\\"model-2-128-1-relu-hidden-identity-output\\">Model: 2 \u2192 128 \u2192 1 (ReLU hidden, identity output)</h3>\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 regression FFN + training loop</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch.nn as nn\\nfrom torch.utils.data import TensorDataset, DataLoader\\n\\ndevice = torch.device(\\"cuda\\" if torch.cuda.is_available() else \\"cpu\\")\\n\\nds = TensorDataset(x, y)\\nloader = DataLoader(ds, batch_size=256, shuffle=True)\\n\\nmodel = nn.Sequential(\\n    nn.Linear(2, 128),\\n    nn.ReLU(),\\n    nn.Linear(128, 1),\\n).to(device)\\n\\ncriterion = nn.MSELoss()\\noptimizer = torch.optim.Adam(model.parameters(), lr=3e-2)\\n\\ndef train_epochs(epochs=50):\\n    model.train()\\n    history = []\\n    for ep in range(epochs):\\n        losses = []\\n        for xb, yb in loader:\\n            xb, yb = xb.to(device), yb.to(device)\\n            optimizer.zero_grad()\\n            pred = model(xb)\\n            loss = criterion(pred, yb)\\n            loss.backward()\\n            optimizer.step()\\n            losses.append(loss.item())\\n        history.append(float(np.mean(losses)))\\n        if (ep + 1) % 10 == 0:\\n            print(f\\"epoch {ep+1:03d} | mse {history[-1]:.6f}\\")\\n    return history\\n\\nloss_hist = train_epochs(epochs=60)</code></pre>\\n      </div>\\n\\n      <h3 id=\\"predict-on-a-grid-meshgrid-model-reshape-surface\\">Predict on a grid: meshgrid \u2192 model \u2192 reshape \u2192 surface</h3>\\n      <p class=\\"muted\\">\\n        To draw a smooth surface, you evaluate the model on a grid of \\\\((x_1, x_2)\\\\) points.\\n        The key is reshaping: grids are 2D, the model wants a 2-column matrix, and the output must be reshaped back to the grid.\\n      </p>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 meshgrid predictions + 3D surface plot (run locally)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>@torch.no_grad()\\ndef plot_surface(model, lim=3.0, steps=80):\\n    model.eval()\\n    xs = torch.linspace(-lim, lim, steps)\\n    ys = torch.linspace(-lim, lim, steps)\\n    X, Y = torch.meshgrid(xs, ys, indexing=\\"ij\\")       # shapes (steps, steps)\\n\\n    grid = torch.stack([X.reshape(-1), Y.reshape(-1)], dim=1).to(device)  # (steps*steps, 2)\\n    Z = model(grid).reshape(steps, steps).cpu()\\n\\n    # Plot\\n    import matplotlib.pyplot as plt\\n    from mpl_toolkits.mplot3d import Axes3D  # noqa: F401\\n    fig = plt.figure(figsize=(7, 5))\\n    ax = fig.add_subplot(111, projection=\\"3d\\")\\n    ax.plot_surface(X.numpy(), Y.numpy(), Z.numpy(), linewidth=0, antialiased=True)\\n    ax.set_xlabel(\\"x1\\"); ax.set_ylabel(\\"x2\\"); ax.set_zlabel(\\"pred y\\")\\n    plt.show()\\n\\nplot_surface(model)</code></pre>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>What you\u2019re checking visually:</b> does the learned surface match the \u201cbumpy\u201d cosine structure?\\n          If not, try adjusting learning rate, epochs, batch size, or hidden width.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"tuning\\">\\n      <h2 id=\\"9-hyperparameters-a-practical-experimentation-workflow\\">9) Hyperparameters: a practical experimentation workflow</h2>\\n\\n      <p>\\n        Hyperparameters (learning rate, batch size, number of epochs, hidden width, optimizer choice) don\u2019t come with universal rules\\n        that always win. A reliable workflow is:\\n      </p>\\n      <ol>\\n        <li><b>Start reasonable</b> (common defaults: Adam or SGD, moderate LR, moderate batch size)</li>\\n        <li><b>Confirm learning</b> (loss decreases; accuracy increases)</li>\\n        <li><b>Search locally</b> (try a small grid around current settings)</li>\\n        <li><b>Use evidence</b> (plots/metrics) to decide next changes</li>\\n      </ol>\\n\\n      <h3 id=\\"minimal-grid-search-skeleton\\">Minimal grid-search skeleton</h3>\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 tiny hyperparameter sweep skeleton</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>def run_experiment(lr, hidden, epochs=3):\\n    model = nn.Sequential(\\n        nn.Linear(28*28, hidden),\\n        nn.ReLU(),\\n        nn.Linear(hidden, 10),\\n    ).to(device)\\n\\n    opt = torch.optim.SGD(model.parameters(), lr=lr)\\n    crit = nn.CrossEntropyLoss()\\n\\n    for _ in range(epochs):\\n        model.train()\\n        for x, y in train_loader:\\n            x = x.view(x.size(0), -1).to(device)\\n            y = y.to(device)\\n            opt.zero_grad()\\n            logits = model(x)\\n            loss = crit(logits, y)\\n            loss.backward()\\n            opt.step()\\n\\n    acc = accuracy_loader(model, test_loader, device)\\n    return acc\\n\\nfor lr in [0.3, 0.1, 0.03]:\\n    for hidden in [64, 128, 256]:\\n        acc = run_experiment(lr=lr, hidden=hidden, epochs=2)\\n        print(f\\"lr={lr:&lt;5} hidden={hidden:&lt;4} -&gt; test acc {acc:.4f}\\")</code></pre>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Goal:</b> don\u2019t hunt for mystical \u201cbest\u201d defaults\u2014build a habit of quick, disciplined experiments.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"credits\\">\\n      <h2 id=\\"local-visuals-and-source-credits\\">Local visuals and source credits</h2>\\n      <ul class=\\"small\\">\\n        <li>Optimizer animation (SGD variants): <a href=\\"https://commons.wikimedia.org/wiki/File:Optimizer_Animations.gif\\" target=\\"_blank\\" rel=\\"noopener\\">Optimizer_Animations.gif</a></li>\\n        <li>Softmax illustration: <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax_en.svg\\" target=\\"_blank\\" rel=\\"noopener\\">Softmax_en.svg</a></li>\\n        <li>Confusion matrix example: <a href=\\"https://commons.wikimedia.org/wiki/File:Confusion_matrix.png\\" target=\\"_blank\\" rel=\\"noopener\\">Confusion_matrix.png</a></li>\\n        <li>3D surface plot example: <a href=\\"https://commons.wikimedia.org/wiki/File:3-D_surface_plot.jpg\\" target=\\"_blank\\" rel=\\"noopener\\">3-D_surface_plot.jpg</a></li>\\n      </ul>\\n\\n      <div class=\\"hr\\"></div>\\n      <p class=\\"muted small\\">\\n        This page serves displayed images from local assets, with source credits retained where applicable.\\n        Code blocks are formatted by the shared book styling and include copy buttons.\\n        When you run the plotting code locally, it will generate the visualizations (this HTML itself does not generate plots).\\n      </p>\\n    </section>\\n\\n  </div>"}'),l={title:"Feed-Forward Networks: Training, Evaluation, and Debugging",slug:"/part5-deep-learning-and-llms/02-ffn-training-debugging",description:"Training at scale with mini-batches, evaluation (accuracy + confusion matrix), and a synthetic regression example for visual intuition.",sidebar_label:"2. FFN training and debugging",pagination_label:"2. FFN training and debugging",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function m(n){return(0,t.jsx)(o.A,{content:r})}function u(n={}){const{wrapper:e}={...(0,s.R)(),...n.components};return e?(0,t.jsx)(e,{...n,children:(0,t.jsx)(m,{...n})}):m()}}}]);